/** 
 * Returns the local user's nickname in the context of this chat room or <tt>null</tt> if not currently joined.
 * @return the nickname currently being used by the local user
 */
public String getUserNickname(){
  final IrcConnection connection=this.parentProvider.getIrcStack().getConnection();
  if (connection == null) {
    throw new IllegalStateException("Connection is not available.");
  }
  return connection.getIdentityManager().getNick();
}
